} Territory;

int n;
Territory territories[MAX_COUNTRIES];
int adj[MAX_COUNTRIES][MAX_COUNTRIES];
int color[MAX_COUNTRIES];
int min_colors;

int on_segment(double px, double py, double qx, double qy, double rx, double ry) {
    if (qx <= fmax(px, rx) && qx >= fmin(px, rx) &&
        qy <= fmax(py, ry) && qy >= fmin(py, ry))
        return 1;
    return 0;
}

int orientation(double px, double py, double qx, double qy, double rx, double ry) {
    double val = (qy - py) * (rx - qx) - (qx - px) * (ry - qy);
    if (val == 0) return 0;
    return (val > 0) ? 1 : 2;
}

int segments_intersect(double p1x, double p1y, double q1x, double q1y,
                        double p2x, double p2y, double q2x, double q2y) {
    int o1 = orientation(p1x, p1y, q1x, q1y, p2x, p2y);
    int o2 = orientation(p1x, p1y, q1x, q1y, q2x, q2y);
    int o3 = orientation(p2x, p2y, q2x, q2y, p1x, p1y);
    int o4 = orientation(p2x, p2y, q2x, q2y, q1x, q1y);

    if (o1 != o2 && o3 != o4)
        return 1;
    if (o1 == 0 && on_segment(p1x, p1y, p2x, p2y, q1x, q1y)) return 1;
    if (o2 == 0 && on_segment(p1x, p1y, q2x, q2y, q1x, q1y)) return 1;
    if (o3 == 0 && on_segment(p2x, p2y, p1x, p1y, q2x, q2y)) return 1;
    if (o4 == 0 && on_segment(p2x, p2y, q1x, q1y, q2x, q2y)) return 1;
    return 0;
}

int share_border(int i, int j) {
    for (int a = 0; a < territories[i].vertex_count; a++) {
        int a_next = (a + 1) % territories[i].vertex_count;
        for (int b = 0; b < territories[j].vertex_count; b++) {
            int b_next = (b + 1) % territories[j].vertex_count;
            if (segments_intersect(
                    territories[i].vertices[a][0], territories[i].vertices[a][1],
                    territories[i].vertices[a_next][0], territories[i].vertices[a_next][1],
                    territories[j].vertices[b][0], territories[j].vertices[b][1],
                    territories[j].vertices[b_next][0], territories[j].vertices[b_next][1])) {
                return 1;
            }
        }
    }
    return 0;
}

int is_safe(int v, int c) {
    for (int i = 0; i < n; i++) {
        if (adj[v][i] && color[i] == c)
            return 0;
    }
    return 1;
}

void graph_coloring(int v) {
    if (v == n) {
        int used = 0;
        int seen[5] = {0};
        for (int i = 0; i < n; i++) {
            if (!seen[color[i]]) {
                seen[color[i]] = 1;
                used++;
            }
        }
        if (used < min_colors) min_colors = used;
        return;
    }
    for (int c = 1; c <= min_colors; c++) {
        if (is_safe(v, c)) {
            color[v] = c;
            graph_coloring(v + 1);
            color[v] = 0;
        }
    }
}

