#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

#define MAXT 205
#define MAXNAME 64
#define MAXP 205
#define EPS 1e-9

typedef struct {
    double x, y;
} Point;

typedef struct {
    char name[MAXNAME];
    int p;
    Point pt[MAXP];
    int country;
} Territory;

typedef struct {
    char name[MAXNAME];
} Country;

static Territory terr[MAXT];
static Country countries[MAXT];
static int countryCount, terrCount;

static int adj[MAXT][MAXT];
static int color[MAXT];
static int degreev[MAXT];
static int best;

/* ---------- Geometry ---------- */

static int dcmp(double x) {
    if (x > EPS) return 1;
    if (x < -EPS) return -1;
    return 0;
}

static double cross(Point a, Point b, Point c) {
    return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
}

static int onSegment(Point a, Point b, Point p) {
    if (dcmp(cross(a, b, p)) != 0) return 0;
    if (p.x < fmin(a.x, b.x) - EPS || p.x > fmax(a.x, b.x) + EPS) return 0;
    if (p.y < fmin(a.y, b.y) - EPS || p.y > fmax(a.y, b.y) + EPS) return 0;
    return 1;
}

static int samePoint(Point a, Point b) {
    return dcmp(a.x - b.x) == 0 && dcmp(a.y - b.y) == 0;
}

/* Check whether segments AB and CD overlap in a non-zero-length segment */
static int collinearOverlapPositive(Point a, Point b, Point c, Point d) {
    if (dcmp(cross(a, b, c)) != 0 || dcmp(cross(a, b, d)) != 0) return 0;

    if (fabs(a.x - b.x) >= fabs(a.y - b.y)) {
        double l1 = fmin(a.x, b.x), r1 = fmax(a.x, b.x);
        double l2 = fmin(c.x, d.x), r2 = fmax(c.x, d.x);
        double L = fmax(l1, l2), R = fmin(r1, r2);
        return R - L > EPS;
    } else {
        double l1 = fmin(a.y, b.y), r1 = fmax(a.y, b.y);
        double l2 = fmin(c.y, d.y), r2 = fmax(c.y, d.y);
        double L = fmax(l1, l2), R = fmin(r1, r2);
        return R - L > EPS;
    }
}

/* Countries are adjacent iff some edges overlap on a segment of positive length */
static int polygonsAdjacent(Territory *A, Territory *B) {
    int i, j;
    for (i = 0; i < A->p; i++) {
        Point a1 = A->pt[i];
        Point a2 = A->pt[(i + 1) % A->p];
        for (j = 0; j < B->p; j++) {
            Point b1 = B->pt[j];
            Point b2 = B->pt[(j + 1) % B->p];
            if (collinearOverlapPositive(a1, a2, b1, b2)) return 1;
        }
    }
    return 0;
}

/* ---------- Country handling ---------- */

static int getCountryId(const char *name) {
    int i;
    for (i = 0; i < countryCount; i++) {
        if (strcmp(countries[i].name, name) == 0) return i;
    }
    strcpy(countries[countryCount].name, name);
    return countryCount++;
}

/* ---------- Graph coloring ---------- */

static int canUse(int v, int c, int n) {
    int i;
    for (i = 0; i < n; i++) {
        if (adj[v][i] && color[i] == c) return 0;
    }
    return 1;
}

static int selectVertex(int n) {
    int i, bestv = -1, bestdeg = -1;
    for (i = 0; i < n; i++) {
        if (color[i] == -1) {
            if (degreev[i] > bestdeg) {
                bestdeg = degreev[i];
                bestv = i;
            }
        }
    }
    return bestv;
}

static void dfsColor(int usedColors, int n) {
    int i, v;

    if (usedColors >= best) return;

    v = selectVertex(n);
    if (v == -1) {
        best = usedColors;
        return;
    }

    for (i = 0; i < usedColors; i++) {
        if (canUse(v, i, n)) {
            color[v] = i;
            dfsColor(usedColors, n);
            color[v] = -1;
        }
    }

    color[v] = usedColors;
    dfsColor(usedColors + 1, n);
    color[v] = -1;
}

/* ---------- Main ---------- */

int main(void) {
    while (scanf("%d", &terrCount) == 1) {
        int i, j, k;

        if (terrCount <= 0) break;

        countryCount = 0;

        for (i = 0; i < terrCount; i++) {
            scanf("%s %d", terr[i].name, &terr[i].p);
            terr[i].country = getCountryId(terr[i].name);
            for (j = 0; j < terr[i].p; j++) {
                scanf("%lf %lf", &terr[i].pt[j].x, &terr[i].pt[j].y);
            }
        }

        memset(adj, 0, sizeof(adj));
        memset(degreev, 0, sizeof(degreev));

        for (i = 0; i < terrCount; i++) {
            for (j = i + 1; j < terrCount; j++) {
                if (terr[i].country == terr[j].country) continue;
                if (polygonsAdjacent(&terr[i], &terr[j])) {
                    int a = terr[i].country;
                    int b = terr[j].country;
                    if (!adj[a][b]) {
                        adj[a][b] = adj[b][a] = 1;
                    }
                }
            }
        }

        for (i = 0; i < countryCount; i++) {
            for (j = 0; j < countryCount; j++) {
                if (adj[i][j]) degreev[i]++;
            }
        }

        for (i = 0; i < countryCount; i++) color[i] = -1;
        best = countryCount;
        dfsColor(0, countryCount);

        printf("%d\n", best);
    }

    return 0;
}

