using namespace std;

struct Point {
    int x, y;
    bool operator==(const Point& p) const { return x == p.x && y == p.y; }
};

using Polygon = vector<Point>;

// Check if two polygons share a border edge
bool shareEdge(const Polygon& a, const Polygon& b) {
    set<pair<Point,Point>> edgesA;
    for (size_t i = 0; i < a.size(); i++) {
        Point p1 = a[i];
        Point p2 = a[(i+1) % a.size()];
        if (p2.x < p1.x || (p2.x == p1.x && p2.y < p1.y)) swap(p1, p2);
        edgesA.insert({p1, p2});
    }
    for (size_t i = 0; i < b.size(); i++) {
        Point p1 = b[i];
        Point p2 = b[(i+1) % b.size()];
        if (p2.x < p1.x || (p2.x == p1.x && p2.y < p1.y)) swap(p1, p2);
        if (edgesA.count({p1, p2})) return true;
    }
    return false;
}

// Check if current coloring is valid for a given node
bool canColor(int node, int col, const vector<vector<int>>& adj, const vector<int>& color) {
    for (int nb : adj[node]) {
        if (color[nb] == col) return false;
    }
    return true;
}

// Backtracking to find minimum colors for a component
int chromaticNumber(const vector<vector<int>>& adj, const vector<int>& nodes) {
    int m = nodes.size();
    if (m == 0) return 0;
    // Map node IDs to 0..m-1
    unordered_map<int,int> id;
    for (int i = 0; i < m; i++) id[nodes[i]] = i;
    vector<vector<int>> compAdj(m);
    for (int u : nodes) {
        for (int v : adj[u]) {
            if (id.count(v)) {
                compAdj[id[u]].push_back(id[v]);
            }
        }
    }

    // Try k = 1..m
    for (int k = 1; k <= m; k++) {
        vector<int> color(m, -1);
        function<bool(int)> dfs = [&](int idx) -> bool {
            if (idx == m) return true;
            for (int c = 0; c < k; c++) {
                if (canColor(idx, c, compAdj, color)) {
                    color[idx] = c;
                    if (dfs(idx+1)) return true;
                    color[idx] = -1;
                }
            }
            return false;
        };
        if (dfs(0)) return k;
    }
    return m;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    unordered_map<string, vector<Polygon>> countryPolygons;
    for (int i = 0; i < n; i++) {
        string name;
        int v;
        cin >> name >> v;
        Polygon poly(v);
        for (int j = 0; j < v; j++) {
            cin >> poly[j].x >> poly[j].y;
        }
        countryPolygons[name].push_back(poly);
    }

    vector<string> countries;
    for (auto& p : countryPolygons) countries.push_back(p.first);
    int C = countries.size();

    // Build adjacency
    vector<vector<int>> adj(C);
    for (int i = 0; i < C; i++) {
        for (int j = i+1; j < C; j++) {
            bool border = false;
            for (auto& polyA : countryPolygons[countries[i]]) {
                for (auto& polyB : countryPolygons[countries[j]]) {
                    if (shareEdge(polyA, polyB)) {
                        border = true;
                        break;
                    }
                }
                if (border) break;
            }
            if (border) {
                adj[i].push_back(j);
                adj[j].push_back(i);
            }
        }
    }

    // Find connected components
    vector<bool> visited(C, false);
    int ans = 0;
    for (int i = 0; i < C; i++) {
        if (!visited[i]) {
            vector<int> comp;
            queue<int> q;
            q.push(i);
            visited[i] = true;
            while (!q.empty()) {
                int u = q.front(); q.pop();
                comp.push_back(u);
                for (int v : adj[u]) {
                    if (!visited[v]) {
                        visited[v] = true;
                        q.push(v);
                    }
                }
            }
            int chi = chromaticNumber(adj, comp);
            ans = max(ans, chi);
        }
    }
    cout << ans << "\n";
    return 0;
}

