using namespace std;

struct Point {
    long long x, y;
    bool operator<(const Point& other) const {
        if (x != other.x) return x < other.x;
        return y < other.y;
    }
    bool operator==(const Point& other) const {
        return x == other.x && y == other.y;
    }
};

static inline long long cross(const Point& a, const Point& b, const Point& c) {
    // (b-a) x (c-a)
    return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
}

static inline bool onSegment(const Point& a, const Point& b, const Point& p) {
    if (cross(a, b, p) != 0) return false;
    return min(a.x, b.x) <= p.x && p.x <= max(a.x, b.x) &&
           min(a.y, b.y) <= p.y && p.y <= max(a.y, b.y);
}

static inline bool segmentsOverlapMoreThanPoint(const Point& a, const Point& b, const Point& c, const Point& d) {
    // assumes collinear
    if (a == b || c == d) return false;

    // If not on same line, false
    if (cross(a, b, c) != 0 || cross(a, b, d) != 0) return false;

    // Use dominant axis
    if (a.x != b.x) {
        long long l1 = min(a.x, b.x), r1 = max(a.x, b.x);
        long long l2 = min(c.x, d.x), r2 = max(c.x, d.x);
        long long L = max(l1, l2), R = min(r1, r2);
        return L < R; // positive-length overlap
    } else {
        long long l1 = min(a.y, b.y), r1 = max(a.y, b.y);
        long long l2 = min(c.y, d.y), r2 = max(c.y, d.y);
        long long L = max(l1, l2), R = min(r1, r2);
        return L < R; // positive-length overlap
    }
}

static inline bool shareBorder(const vector<Point>& p1, const vector<Point>& p2) {
    int n = (int)p1.size();
    int m = (int)p2.size();

    for (int i = 0; i < n; ++i) {
        Point a = p1[i], b = p1[(i + 1) % n];
        for (int j = 0; j < m; ++j) {
            Point c = p2[j], d = p2[(j + 1) % m];
            if (segmentsOverlapMoreThanPoint(a, b, c, d)) return true;
        }
    }
    return false;
}

bool canColorK(const vector<int>& order, const vector<unsigned long long>& adjMask, vector<int>& color, int idx, int k) {
    int n = (int)order.size();
    if (idx == n) return true;

    int u = order[idx];
    for (int c = 0; c < k; ++c) {
        bool ok = true;
        unsigned long long mask = adjMask[u];
        while (mask) {
            int v = __builtin_ctzll(mask);
            mask &= mask - 1;
            if (color[v] == c) {
                ok = false;
                break;
            }
        }
        if (!ok) continue;
        color[u] = c;
        if (canColorK(order, adjMask, color, idx + 1, k)) return true;
        color[u] = -1;
    }
    return false;
}

int chromaticNumber(const vector<unsigned long long>& adjMask, int n) {
    if (n == 0) return 0;
    if (n == 1) return 1;

    vector<int> degree(n);
    for (int i = 0; i < n; ++i) degree[i] = __builtin_popcountll(adjMask[i]);

    vector<int> order(n);
    iota(order.begin(), order.end(), 0);
    sort(order.begin(), order.end(), [&](int a, int b) {
        return degree[a] > degree[b];
    });

    vector<int> color(n, -1);
    for (int k = 1; k <= 4; ++k) {
        fill(color.begin(), color.end(), -1);
        if (canColorK(order, adjMask, color, 0, k)) return k;
    }
    return 4; // planar map theorem
}

