        for (int i = 0; i < R; ++i) {
            string name;
            int v;
            cin >> name >> v;
            regionCountry[i] = name;
            if (!countryId.count(name)) countryId[name] = countryCnt++;

            polygons[i].resize(v);
            for (int j = 0; j < v; ++j) cin >> polygons[i][j].x >> polygons[i][j].y;
        }

        vector<unsigned long long> adj(countryCnt, 0);

        for (int i = 0; i < R; ++i) {
            int ci = countryId[regionCountry[i]];
            for (int j = i + 1; j < R; ++j) {
                int cj = countryId[regionCountry[j]];
                if (ci == cj) continue;
                if (shareBorder(polygons[i], polygons[j])) {
                    adj[ci] |= (1ULL << cj);
                    adj[cj] |= (1ULL << ci);
                }
            }
        }

        cout << chromaticNumber(adj, countryCnt) << "\n";
    }

    return 0;
}

