public class Main {
    static int n;
    static List<Integer>[] graph;
    static int[] color;
    static int minColors;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder sb = new StringBuilder();
        String line;
        while ((line = br.readLine()) != null) {
            line = line.trim();
            if (line.isEmpty()) continue;
            int t = Integer.parseInt(line);
            if (t == 0) break;

            Map<String, List<List<int[]>>> countryTerritories = new LinkedHashMap<>();
            List<String> countryOrder = new ArrayList<>();

            // Read t territories
            for (int i = 0; i < t; i++) {
                String[] parts = br.readLine().trim().split("\\s+");
                String countryName = parts[0];
                int v = Integer.parseInt(parts[1]);
                List<int[]> vertices = new ArrayList<>();
                int idx = 2;
                for (int j = 0; j < v; j++) {
                    int x = Integer.parseInt(parts[idx++]);
                    int y = Integer.parseInt(parts[idx++]);
                    vertices.add(new int[]{x, y});
                }
                countryTerritories
                    .computeIfAbsent(countryName, k -> new ArrayList<>())
                    .add(vertices);
                if (!countryOrder.contains(countryName)) {
                    countryOrder.add(countryName);
                }
            }

            n = countryOrder.size();
            Map<String, Integer> nameToIdx = new HashMap<>();
            for (int i = 0; i < n; i++) {
                nameToIdx.put(countryOrder.get(i), i);
            }

            // Build graph
            graph = new ArrayList[n];
            for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();

            // For each pair of countries, check if they share a border
            for (int i = 0; i < n; i++) {
                for (int j = i + 1; j < n; j++) {
                    if (shareBorder(countryTerritories.get(countryOrder.get(i)),
                                    countryTerritories.get(countryOrder.get(j)))) {
                        graph[i].add(j);
                        graph[j].add(i);
                    }
                }
            }

            // Solve chromatic number
            color = new int[n];
            Arrays.fill(color, -1);
            minColors = n; // upper bound
            // Greedy upper bound
            int greedyColors = greedyColoring();
            minColors = Math.min(minColors, greedyColors);
            // Backtracking search from lower bound 1 to minColors-1
            for (int c = 1; c < greedyColors; c++) {
                Arrays.fill(color, -1);
                if (backtrack(0, c)) {
                    minColors = c;
                    break;
                }
            }

            sb.append(minColors).append("\n");
        }
        System.out.print(sb.toString());
    }

    static boolean shareBorder(List<List<int[]>> polysA, List<List<int[]>> polysB) {
        for (List<int[]> polyA : polysA) {
            for (List<int[]> polyB : polysB) {
                if (polygonsShareEdge(polyA, polyB)) return true;
            }
        }
        return false;
    }

    static boolean polygonsShareEdge(List<int[]> poly1, List<int[]> poly2) {
        Set<String> edges1 = getEdgeSet(poly1);
        Set<String> edges2 = getEdgeSet(poly2);
        for (String e : edges1) {
            if (edges2.contains(e)) return true;
        }
        return false;
    }

    static Set<String> getEdgeSet(List<int[]> poly) {
        Set<String> set = new HashSet<>();
        int m = poly.size();
        for (int i = 0; i < m; i++) {
            int[] a = poly.get(i);
            int[] b = poly.get((i + 1) % m);
            int x1 = a[0], y1 = a[1], x2 = b[0], y2 = b[1];
            if (x1 > x2 || (x1 == x2 && y1 > y2)) {
                int tmpX = x1; x1 = x2; x2 = tmpX;
                int tmpY = y1; y1 = y2; y2 = tmpY;
            }
            set.add(x1 + "," + y1 + "-" + x2 + "," + y2);
        }
        return set;
    }

    static int greedyColoring() {
        int[] col = new int[n];
        Arrays.fill(col, -1);
        col[0] = 0;
        boolean[] used = new boolean[n];
        for (int u = 1; u < n; u++) {
            Arrays.fill(used, false);
            for (int v : graph[u]) {
                if (col[v] != -1) used[col[v]] = true;
            }
            int cr;
            for (cr = 0; cr < n; cr++) if (!used[cr]) break;
            col[u] = cr;
        }
        int max = 0;
        for (int c : col) max = Math.max(max, c);
        return max + 1;
    }

    static boolean backtrack(int idx, int maxColors) {
        if (idx == n) return true;
        // Choose vertex with most colored neighbors (small improvement)
        int u = -1;
        int maxDeg = -1;
        for (int i = 0; i < n; i++) {
            if (color[i] == -1) {
                int cnt = 0;
                for (int v : graph[i]) if (color[v] != -1) cnt++;
                if (cnt > maxDeg) {
                    maxDeg = cnt;
                    u = i;
                }
            }
        }
        boolean[] used = new boolean[maxColors];
        for (int v : graph[u]) {
            if (color[v] != -1) used[color[v]] = true;
        }
        for (int c = 0; c < maxColors; c++) {
            if (!used[c]) {
                color[u] = c;
                if (backtrack(idx + 1, maxColors)) return true;
                color[u] = -1;
            }
        }
        return false;
    }
