/*
 * Map Coloring with countries having multiple polygonal territories.
 *
 * We build the country adjacency graph:
 * - Each territory is a polygon.
 * - Two countries are adjacent if any territory edge of one overlaps
 *   with any territory edge of the other by a positive-length segment.
 *   Touching only at a point does NOT make them adjacent.
 * - All territories of the same country must receive the same color.
 *
 * Then we compute the chromatic number of the country graph.
 *
 * Input format assumed:
 * Repeated test cases until EOF.
 * For each test case:
 *   n
 *   then n territories, each as:
 *     countryName m x1 y1 x2 y2 ... xm ym
 *
 * Output:
 *   one line per test case: minimum number of colors
 *
 * This matches the classic "map" style input where every territory is given
 * independently, and countries may appear multiple times.
 */

public class Main {

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (c <= 32);
            while (c > 32) {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    static class Point {
        long x, y;
        Point(long x, long y) {
            this.x = x;
            this.y = y;
        }
    }

    static class Territory {
        int country;
        Point[] p;
        Territory(int country, Point[] p) {
            this.country = country;
            this.p = p;
        }
    }

    static long cross(Point a, Point b, Point c) {
        return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
    }

    static boolean between(long a, long b, long x) {
        return Math.min(a, b) <= x && x <= Math.max(a, b);
    }

    static boolean onSegment(Point a, Point b, Point p) {
        return cross(a, b, p) == 0 && between(a.x, b.x, p.x) && between(a.y, b.y, p.y);
    }

    // Returns true iff segments AB and CD overlap on a positive-length collinear part.
    // This is the correct notion of map adjacency by shared border.
    static boolean shareBorder(Point a, Point b, Point c, Point d) {
        long c1 = cross(a, b, c);
        long c2 = cross(a, b, d);
        if (c1 != 0 || c2 != 0) return false; // not collinear

        // If collinear, check whether intersection is more than a point.
        if (a.x != b.x) {
            long l = Math.max(Math.min(a.x, b.x), Math.min(c.x, d.x));
            long r = Math.min(Math.max(a.x, b.x), Math.max(c.x, d.x));
            return l < r;
        } else {
            long l = Math.max(Math.min(a.y, b.y), Math.min(c.y, d.y));
            long r = Math.min(Math.max(a.y, b.y), Math.max(c.y, d.y));
            return l < r;
        }
    }

    static boolean adjacent(Territory t1, Territory t2) {
        Point[] a = t1.p, b = t2.p;
        for (int i = 0; i < a.length; i++) {
            Point a1 = a[i];
            Point a2 = a[(i + 1) % a.length];
            for (int j = 0; j < b.length; j++) {
                Point b1 = b[j];
                Point b2 = b[(j + 1) % b.length];
                if (shareBorder(a1, a2, b1, b2)) return true;
            }
        }
        return false;
    }

    static int nCountries;
    static long[] adj;
    static int[] color;
    static int[] order;

    static boolean canColorWithK(int k) {
        Arrays.fill(color, -1);
        return dfsColor(0, k);
    }

    static boolean dfsColor(int idx, int k) {
        if (idx == nCountries) return true;
        int v = order[idx];

        boolean[] used = new boolean[k];
        long mask = adj[v];
        while (mask != 0) {
            int u = Long.numberOfTrailingZeros(mask);
            mask &= mask - 1;
            if (color[u] != -1) used[color[u]] = true;
        }

        for (int c = 0; c < k; c++) {
            if (!used[c]) {
                color[v] = c;
                if (dfsColor(idx + 1, k)) return true;
                color[v] = -1;
            }
        }
        return false;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        String first;
        StringBuilder out = new StringBuilder();

        while ((first = fs.next()) != null) {
            int n = Integer.parseInt(first);
            Map<String, Integer> countryId = new HashMap<>();
            List<Territory> territories = new ArrayList<>();

            for (int i = 0; i < n; i++) {
                String name = fs.next();
                int m = fs.nextInt();
                Point[] poly = new Point[m];
                for (int j = 0; j < m; j++) {
                    long x = Long.parseLong(fs.next());
                    long y = Long.parseLong(fs.next());
                    poly[j] = new Point(x, y);
                }
                Integer id = countryId.get(name);
                if (id == null) {
                    id = countryId.size();
                    countryId.put(name, id);
                }
                territories.add(new Territory(id, poly));
            }

            nCountries = countryId.size();
            adj = new long[nCountries];

            for (int i = 0; i < territories.size(); i++) {
                Territory a = territories.get(i);
                for (int j = i + 1; j < territories.size(); j++) {
                    Territory b = territories.get(j);
                    if (a.country == b.country) continue;
                    if (adjacent(a, b)) {
                        adj[a.country] |= 1L << b.country;
                        adj[b.country] |= 1L << a.country;
                    }
                }
            }

            Integer[] ord = new Integer[nCountries];
            for (int i = 0; i < nCountries; i++) ord[i] = i;
            Arrays.sort(ord, (u, v) -> Long.bitCount(adj[v]) - Long.bitCount(adj[u]));
            order = new int[nCountries];
            for (int i = 0; i < nCountries; i++) order[i] = ord[i];

            color = new int[nCountries];

            int answer = 0;
            if (nCountries == 0) {
                answer = 0;
            } else {
                for (int k = 1; k <= nCountries; k++) {
                    if (canColorWithK(k)) {
                        answer = k;
                        break;
                    }
                }
            }

            out.append(answer).append('\n');
        }

        System.out.print(out.toString());
    }
